import React, { useState, useEffect, useRef } from 'react';

const VoiceWeb = () => {
  const [messages, setMessages] = useState([]);
  const [isLive, setIsLive] = useState(false);
  const [caption, setCaption] = useState("Press here to activate the mic");
  const [inputValue, setInputValue] = useState('');

  // State management for interactive branching
  const [currentService, setCurrentService] = useState(null);
  const [step, setStep] = useState('language'); 
  const scrollRef = useRef(null);

  const speak = (text, lang = 'en-IN') => {
    const msg = new SpeechSynthesisUtterance(text);
    msg.lang = lang;
    window.speechSynthesis.speak(msg);
  };

  const addMessage = (sender, text, image = null) => {
    const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    setMessages(prev => [...prev, { sender, text, time, image }]);
  };

  const startSession = () => {
    setIsLive(true);
    addMessage("Voice Web", "Welcome to SkySync. Please select your language.");
    speak("Welcome to Sky Sync. Please select your preferred language.");

    const languages = [
      { msg: "For English, Press 1", lang: "en-GB" },
      { msg: "తెలుగు కోసం, రెండు నొక్కండి", lang: "te-IN" }, // Updated numbering
      { msg: "हिंदी के लिए, तीन दबाएं", lang: "hi-IN" },
      { msg: "Malayalam, 4", lang: "ml-IN" },
      { msg: "Tamil, 5", lang: "ta-IN" },
      { msg: "Kannada, 6", lang: "kn-IN" },
      { msg: "Bengali, 7", lang: "bn-IN" },
      { msg: "Marathi, 8", lang: "mr-IN" },
      { msg: "Gujarati, 9", lang: "gu-IN" },
      { msg: "Punjabi, 10", lang: "pa-IN" }
    ];

    languages.forEach((item, index) => {
      setTimeout(() => {
        setCaption(item.msg);
        speak(item.msg, item.lang);
        if(index === languages.length - 1) setTimeout(() => startListening(), 2000);
      }, (index + 1) * 2000);
    });
  };

  const startListening = () => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();
    recognition.start();
    recognition.onresult = (event) => handleInteraction(event.results[0][0].transcript);
  };

  const handleInteraction = (val) => {
    const input = val.toLowerCase();
    addMessage("You", val);

    // --- STAGE 1: LANGUAGE SELECTION ---
    if (step === 'language') {
      if (input.includes("telugu") || input.includes("2") || input.includes("తెలుగు")) {
        setStep('service_selection');
        speak("తెలుగు ఎంపిక చేయబడింది. మా సేవలు ఇక్కడ ఉన్నాయి. దయచేసి ఒకదాన్ని ఎంచుకోండి.", "te-IN");
        addMessage("Voice Web", "Services: 1.Booking, 2.Status, 3.Check-in, 4.Baggage, 5.Refund, 6.Lounge, 7.Assistance, 8.Loyalty, 9.Agent, 10.Info");
      }
    } 

    // --- STAGE 2: SERVICE ROUTING ---
    else if (step === 'service_selection') {
      if (input.includes("booking") || input.includes("1")) {
        setCurrentService('booking');
        setStep('booking_dest');
        speak("Flight Booking selected. Where would you like to fly?", "en-IN");
        addMessage("Voice Web", "Booking Flow: Please state your Destination.");
      } else if (input.includes("check-in") || input.includes("checkin") || input.includes("3")) {
        setCurrentService('checkin');
        setStep('checkin_pnr');
        speak("Web Check-in selected. Please provide your PNR number to start.", "en-IN");
        addMessage("Voice Web", "Check-in Flow: Please enter or speak your PNR.");
      } else if (input.includes("refund") || input.includes("5")) {
        setCurrentService('refund');
        setStep('refund_pnr');
        speak("Refund processing selected. What is your PNR?", "en-IN");
        addMessage("Voice Web", "Refund Flow: Provide PNR for verification.");
      }
    }

    // --- STAGE 3: INTERACTIVE BRANCHES ---

    // BRANCH A: BOOKING
    else if (step === 'booking_dest') {
      setStep('booking_final');
      const pnr = "BK" + Math.floor(Math.random() * 90000);
      addMessage("Voice Web", `Confirmed! PNR: ${pnr}, Gate: A1, Weather: 30°C, Economy Class.`, "https://img.icons8.com/fluency/48/checked-checkbox.png");
      speak("Your booking is successful. PNR is generated.");
    }

    // BRANCH B: CHECK-IN (Your Specific Requirement)
    else if (step === 'checkin_pnr') {
      setStep('checkin_final');
      addMessage("Voice Web", "PNR Verified. Baggage allowed: 15kg Cabin, 7kg Hand. Seat 12F Assigned.", "https://img.icons8.com/fluency/48/luggage.png");
      speak("Check-in successful. You are allowed 15 kg baggage. Your seat is 12 F.");
    }

    setInputValue('');
  };

  return (
    <div style={{background: '#f1f5f9', height: '100vh', display: 'flex', flexDirection: 'column'}}>

      {/* HEADER - LOCKED UI */}
      <div style={{background: 'white', padding: '10px 40px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #e2e8f0'}}>
        <div style={{display: 'flex', alignItems: 'center', gap: '12px'}}>
           <div style={{background: '#2563eb', color: 'white', width: '35px', height: '35px', display: 'flex', justifyContent: 'center', alignItems: 'center', borderRadius: '8px'}}>✈️</div>
           <b style={{fontSize: '15px'}}>SKY-SYNC <span style={{fontSize: '10px', color: '#64748b', display: 'block'}}>VOICE ASSISTANT</span></b>
        </div>
        <div style={{display: 'flex', gap: '5px', background: '#f8fafc', padding: '5px', borderRadius: '30px'}}>
           <button style={{padding: '5px 15px', borderRadius: '20px', border: 'none', background: 'transparent'}}>Voice Call</button>
           <button style={{padding: '5px 15px', borderRadius: '20px', border: 'none', background: '#2563eb', color: 'white'}}>Voice Web</button>
        </div>
        <div style={{display: 'flex', alignItems: 'center', gap: '15px'}}>
           <span>🔔</span><span>❓</span>
           <div style={{width: '35px', height: '35px', borderRadius: '50%', background: '#cbd5e1'}}></div>
        </div>
      </div>

      {/* MAIN CONTENT - 3 COLUMN LOCKED */}
      <div style={{display: 'grid', gridTemplateColumns: '260px 1fr 280px', gap: '20px', padding: '20px', flex: 1, overflow: 'hidden'}}>

        {/* LEFT: SERVICES LIST */}
        <div style={{background: 'white', borderRadius: '20px', padding: '20px'}}>
          <h4 style={{fontSize: '14px', marginBottom: '15px'}}>Services</h4>
          {['Booking', 'Status', 'Check-in', 'Baggage', 'Refund', 'Lounge', 'Assistance', 'Loyalty', 'Agent', 'Info'].map((s, i) => (
            <div key={i} style={{padding: '10px', marginBottom: '5px', borderRadius: '10px', fontSize: '12px', background: i===0 ? '#eff6ff' : 'transparent'}}>
               📄 {s}
            </div>
          ))}
        </div>

        {/* MIDDLE: SPLIT MIC & TRANSCRIPT */}
        <div style={{display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px'}}>
           <div style={{background: 'white', borderRadius: '20px', padding: '20px', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center'}}>
              <p style={{fontSize: '12px', color: '#64748b'}}>{caption}</p>
              <div onClick={startSession} style={{width: '180px', height: '180px', borderRadius: '50%', background: 'radial-gradient(circle, #2563eb 0%, #1e3a8a 100%)', display: 'flex', justifyContent: 'center', alignItems: 'center', color: 'white', cursor: 'pointer'}} className={isLive ? 'pulse-mic' : ''}>
                 <span style={{fontSize: '50px'}}>🎙️</span>
              </div>
           </div>

           <div style={{background: 'white', borderRadius: '20px', padding: '20px', display: 'flex', flexDirection: 'column', overflow: 'hidden'}}>
              <b style={{fontSize: '12px', marginBottom: '10px'}}>Live Transcript</b>
              <div style={{flex: 1, overflowY: 'auto'}} ref={scrollRef}>
                {messages.map((m, i) => (
                  <div key={i} style={{marginBottom: '10px', background: m.sender === 'You' ? '#eff6ff' : '#f8fafc', padding: '10px', borderRadius: '10px', fontSize: '12px'}}>
                    <b>{m.sender}:</b> {m.text}
                    {m.image && <img src={m.image} alt="icon" style={{width: '30px', display: 'block', marginTop: '5px'}} />}
                  </div>
                ))}
              </div>
           </div>
        </div>

        {/* RIGHT: SUGGESTIONS */}
        <div style={{background: 'white', borderRadius: '20px', padding: '20px'}}>
           <h4 style={{fontSize: '14px', marginBottom: '15px'}}>Quick Help</h4>
           {['Track My Flight', 'Airport Weather', 'Terminal Info'].map(q => (
             <div key={q} style={{padding: '10px', border: '1px solid #f1f5f9', borderRadius: '10px', fontSize: '11px', marginBottom: '5px'}}>
               🔗 {q}
             </div>
           ))}
        </div>
      </div>

      {/* BOTTOM INPUT BAR */}
      <div style={{background: 'white', padding: '15px 40px', borderTop: '1px solid #e2e8f0', display: 'flex', gap: '15px'}}>
        <input 
          type="text" 
          placeholder="Type or speak..." 
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && handleInteraction(inputValue)}
          style={{flex: 1, padding: '12px 25px', borderRadius: '30px', border: '1px solid #e2e8f0', background: '#f8fafc'}} 
        />
        <button onClick={() => handleInteraction(inputValue)} style={{background: '#2563eb', color: 'white', border: 'none', padding: '0 20px', borderRadius: '30px'}}>Send</button>
      </div>

      <style>{`
        .pulse-mic { animation: ripple 1.8s infinite; }
        @keyframes ripple {
          0% { box-shadow: 0 0 0 0 rgba(37, 99, 235, 0.4); }
          70% { box-shadow: 0 0 0 30px rgba(37, 99, 235, 0); }
          100% { box-shadow: 0 0 0 0 rgba(37, 99, 235, 0); }
        }
      `}</style>
    </div>
  );
};

export default VoiceWeb;
